+#include <ranges>
+#include <string>
+#include <fmt/ranges.h>
+
+struct X {
+  template <std::ranges::range R>
+  X(R&& r) : sv(&*std::ranges::begin(r), std::ranges::distance(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+
+  std::string_view sv;
+};
+
+int main() {
+  std::string line = "a,b-c,d-e,f";
+  auto split = line | std::views::split(',');
+  if (fmt::format("{}", split) !=
+      "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]")
+    return 1;
+
+  auto x = split | std::views::transform([](auto part) { return X(part); });
+  if (fmt::format("{}", x) !=
+      "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]")
+    return 2;
+
+  auto nested = split | std::views::transform(std::views::split('-'));
+  return fmt::format("{}", nested) ==
+                 "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]"
+             ? 0
+             : 3;
+}
*** End Patch

